// Images generated by the maker's own account (Q423-Q429): Gemini's image
// models with a Gemini API key or on Vertex AI, OpenAI's with an OpenAI key.
// At most 2K; up to four images of the project as references, to keep one
// style or to retouch the maker's own. The maker's account pays for each.
import { GoogleGenAI } from "@google/genai";
import type { ImageAccount, ImageAspect } from "../../shared/image-models";

/** At most this many images of the project go with a prompt (Q429). */
export const MAX_REFERENCES = 4;
/** At most this many generations a turn; beyond, the agent asks the maker (Q426). */
export const GENERATIONS_A_TURN = 8;

export type Reference = { data: Buffer; mimeType: string };
export type GenerateRequest = { prompt: string; aspect: ImageAspect; references: Reference[] };
export type GeneratedImage = { data: Buffer; mimeType: string };

/** How an account is reached: a key, or Vertex AI on gcloud's sign-in for a project. */
export type ImageCredentials =
  | { account: "gemini" | "openai"; key: string }
  | { account: "vertex"; key: string }
  | { account: "vertex"; project: string; location: string };

/** Generates one image with a model of an account ("gemini-nano-banana-2.1", "gpt-image-2"). */
export async function generateImage(
  credentials: ImageCredentials,
  model: string,
  request: GenerateRequest,
  signal?: AbortSignal,
  get: typeof fetch = fetch,
): Promise<GeneratedImage> {
  if (credentials.account === "openai") return openaiImage(credentials.key, model, request, signal, get);
  return geminiImage(credentials, model, request, signal);
}

/** Gemini's image models answer an image among the reply's parts, whether by its API or Vertex AI. */
async function geminiImage(
  credentials: Exclude<ImageCredentials, { account: "openai" }>,
  model: string,
  { prompt, aspect, references }: GenerateRequest,
  signal?: AbortSignal,
): Promise<GeneratedImage> {
  const ai =
    credentials.account === "gemini"
      ? new GoogleGenAI({ apiKey: credentials.key })
      : "key" in credentials
        ? new GoogleGenAI({ vertexai: true, apiKey: credentials.key })
        : new GoogleGenAI({ vertexai: true, project: credentials.project, location: credentials.location });
  const response = await ai.models.generateContent({
    model,
    contents: [
      {
        role: "user",
        parts: [
          ...references.map((r) => ({ inlineData: { mimeType: r.mimeType, data: r.data.toString("base64") } })),
          { text: prompt },
        ],
      },
    ],
    config: {
      responseModalities: ["IMAGE"],
      imageConfig: { aspectRatio: aspect, imageSize: "2K" },
      ...(signal ? { abortSignal: signal } : {}),
    },
  });
  const parts = response.candidates?.[0]?.content?.parts ?? [];
  const image = parts.find((p) => p.inlineData?.data)?.inlineData;
  if (!image?.data) {
    const said = parts
      .flatMap((p) => (p.text ? [p.text] : []))
      .join(" ")
      .trim();
    const reason = response.candidates?.[0]?.finishReason ?? response.promptFeedback?.blockReason;
    throw new Error(
      `No image came back${reason ? ` (${reason})` : ""}${said ? `: ${said.slice(0, 300)}` : ""}. Describe it otherwise, or find a free photo instead.`,
    );
  }
  return { data: Buffer.from(image.data, "base64"), mimeType: image.mimeType ?? "image/png" };
}

/** OpenAI's sizes at about 2K for each shape: multiples of 16, as its custom sizes ask. */
export const OPENAI_SIZES: Record<ImageAspect, string> = {
  "1:1": "2048x2048",
  "4:3": "2048x1536",
  "3:4": "1536x2048",
  "16:9": "2048x1152",
  "9:16": "1152x2048",
  "21:9": "2048x880",
};

/** OpenAI's image API: a generation from the prompt, or an edit of the references with it. */
async function openaiImage(
  key: string,
  model: string,
  { prompt, aspect, references }: GenerateRequest,
  signal: AbortSignal | undefined,
  get: typeof fetch,
): Promise<GeneratedImage> {
  const size = OPENAI_SIZES[aspect];
  let response: Response;
  if (references.length) {
    const form = new FormData();
    form.set("model", model);
    form.set("prompt", prompt);
    form.set("size", size);
    form.set("quality", "medium");
    references.forEach((r, i) => {
      form.append("image[]", new Blob([new Uint8Array(r.data)], { type: r.mimeType }), `reference-${i + 1}`);
    });
    response = await get("https://api.openai.com/v1/images/edits", {
      method: "POST",
      headers: { authorization: `Bearer ${key}` },
      body: form,
      signal,
    });
  } else
    response = await get("https://api.openai.com/v1/images/generations", {
      method: "POST",
      headers: { authorization: `Bearer ${key}`, "content-type": "application/json" },
      body: JSON.stringify({ model, prompt, size, quality: "medium", n: 1 }),
      signal,
    });
  const body = (await response.json().catch(() => ({}))) as {
    data?: { b64_json?: string }[];
    error?: { message?: string };
  };
  if (!response.ok) throw new Error(`OpenAI answered ${response.status}: ${body.error?.message ?? "no image"}.`);
  const data = body.data?.[0]?.b64_json;
  if (!data) throw new Error("No image came back. Describe it otherwise, or find a free photo instead.");
  return { data: Buffer.from(data, "base64"), mimeType: "image/png" };
}

/** The account of a model's id ("openai/gpt-image-2"), and its own id. */
export function splitImageModel(id: string): { account: ImageAccount; model: string } {
  const at = id.indexOf("/");
  return { account: id.slice(0, at) as ImageAccount, model: id.slice(at + 1) };
}
